export const SpaeherTool: React.FC = () => {
    const { addDocument, toolInput, setToolInput } = useTasks();
    const [query, setQuery] = useState('Latest trends in AI-powered marketing automation');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [briefing, setBriefing] = useState<IntelligenceBrief | null>(null);
    const [sources, setSources] = useState<Source[]>([]);
    const [toastMessage, setToastMessage] = useState<string | null>(null);

    // Handle Auto-Trigger from Conductor
    useEffect(() => {
        if (toolInput && toolInput.tool === 'spaeher' && toolInput.prompt) {
            setQuery(toolInput.prompt);
            handleRecon(toolInput.prompt);
            setToolInput(null);
        }
    }, [toolInput, setToolInput]);

    const reconSchema = {
        type: Type.OBJECT,
        properties: {
            summary: { type: Type.STRING, description: "A concise summary of the findings." },
            key_findings: { type: Type.ARRAY, description: "A list of 3-5 key bullet points.", items: { type: Type.STRING } },
            sentiment: { type: Type.STRING, enum: ['Positive', 'Neutral', 'Negative'], description: "The overall sentiment of the search results." }
        }
    };

    const handleRecon = async (overrideQuery?: string) => {
        const activeQuery = overrideQuery || query;
