                </button>
            </div>
        );
    };

    return (
        <div className="grid lg:grid-cols-3 gap-8">
            <div className="lg:col-span-1 bg-[#1C1C1C] rounded-lg border border-[#333333] p-6 space-y-6 h-fit">
