                            {isOptimizing ? 'Optimiere...' : 'Inhalte für Kanäle optimieren'}
                        </button>
                    </div>

                    { (isOptimizing || optimizedContent) && (
                        <div>
                             <h4 className="text-sm font-medium text-gray-300 mb-2">3. Vorschau</h4>
                             <div className="space-y-3 max-h-64 overflow-y-auto pr-2">
