                                            <div className="flex gap-1.5 mt-2">
                                                {(post.channels || []).map(c => <div key={c} className="text-gray-400" title={c}>{CHANNEL_ICONS[c]}</div>)}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            );
                        })}
                    </div>
                </main>
            </div>
        </>
    );
};
