const BurndownChart: React.FC<{ tasks: Task[] }> = ({ tasks }) => {
    const data = useMemo(() => {
        const total = tasks.length;
        if (total === 0) return { labels: [], ideal: [], actual: [] };

        const days = 14;
        const labels = Array.from({ length: days }, (_, i) => `T-${days - i - 1}`);
        const ideal = Array.from({ length: days }, (_, i) => Math.round(total - (total / (days - 1)) * i));

        // Simulate actual progress
        let actualProgress = total;
        const actual = Array.from({ length: days }, (_, i) => {
            if (i > 5 && i < 12) { // Simulate a slower period
                 actualProgress -= (Math.random() * (total / days) * 0.5);
            } else {
                 actualProgress -= (Math.random() * (total / days) * 1.5);
            }
            return Math.max(0, Math.round(actualProgress));
        });

        return { labels, ideal, actual };
    }, [tasks]);

    const height = 150;
    const width = 300;
    const maxTasks = tasks.length;

    const toPath = (d: number[]) => `M 0 ${height - (d[0]/maxTasks)*height} ` + d.map((p, i) => `L ${(i/(d.length-1))*width} ${height - (p/maxTasks)*height}`).join(' ');

    return (
        <div className="bg-[#0A0A0A] p-4 rounded-lg border border-[#333333]">
            <h3 className="text-sm font-semibold text-white mb-2 flex items-center gap-2"><ChartIcon /> Burndown-Chart (Letzte 14T)</h3>
            {tasks.length > 0 ? (
                <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-auto">
                    <path d={toPath(data.ideal)} stroke="#4A5568" strokeWidth="2" fill="none" strokeDasharray="4"/>
                    <path d={toPath(data.actual)} stroke="#4299E1" strokeWidth="2.5" fill="none"/>
                </svg>
            ) : <p className="text-xs text-center text-gray-500 py-10">Keine Aufgabendaten für Chart vorhanden.</p>}
        </div>
    );
};

const BudgetWidget: React.FC<{ tasks: Task[], navigateTo: (page: string) => void }> = ({ tasks, navigateTo }) => {
    const { totalBudgeted, totalActual } = useMemo(() => {
        const totalBudgeted = tasks.reduce((sum, task) => sum + (task.budgetedCost || 0), 0);
        const totalActual = tasks.reduce((sum, task) => sum + (task.actualCost || 0), 0);
        return { totalBudgeted, totalActual };
    }, [tasks]);

    const percentage = totalBudgeted > 0 ? Math.min((totalActual / totalBudgeted) * 100, 100) : 0;
    const colorClass = percentage > 95 ? 'bg-red-500' : percentage > 75 ? 'bg-yellow-500' : 'bg-green-500';

    return (
        <div onClick={() => navigateTo('kalkulator')} className="bg-[#0A0A0A] p-4 rounded-lg border border-[#333333] cursor-pointer hover:border-white/50">
             <h3 className="text-sm font-semibold text-white mb-2 flex items-center gap-2"><BudgetIcon/> Budget-Auslastung</h3>
             <div className="w-full bg-gray-700/50 rounded-full h-2.5">
                <div className={`${colorClass} h-2.5 rounded-full`} style={{ width: `${percentage}%` }}></div>
            </div>
            <p className="text-xs text-gray-400 mt-2 text-right">{new Intl.NumberFormat('de-DE').format(totalActual)}€ / {new Intl.NumberFormat('de-DE').format(totalBudgeted)}€</p>
        </div>
    );
};


const StrategicAlignmentWidget: React.FC<{ tasks: Task[], campaignBrief: any }> = ({ tasks, campaignBrief }) => {
    const [alignmentScore, setAlignmentScore] = useState<number | null>(null);
    const [advice, setAdvice] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleCheckAlignment = async () => {
        if (!campaignBrief) {
            setAdvice("Keine aktive Kampagnenstrategie gefunden.");
            return;
        }
        setIsLoading(true);
        const prompt = `
            Act as a Strategic Auditor. Compare the current tasks against the campaign brief.

            Campaign Brief: ${JSON.stringify(campaignBrief)}
            Active Tasks: ${JSON.stringify(tasks.slice(0, 10).map(t => t.title))}

            Calculate a 'Strategic Alignment Score' (0-100) based on how well the tasks implement the brief.
            Provide one concise sentence of advice.

            Output JSON: { "score": 85, "advice": "..." }
        `;

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            const response = await ai.models.generateContent({
                 model: 'gemini-3-pro-preview', 
                 contents: prompt,
                 config: { responseMimeType: 'application/json' }
            });
            const data = JSON.parse(response.text);
            setAlignmentScore(data.score);
            setAdvice(data.advice);
        } catch (e) { console.error(e); setAdvice("Analyse fehlgeschlagen."); }
        finally { setIsLoading(false); }
    };

    return (
        <div className="bg-[#0A0A0A] p-4 rounded-lg border border-[#333333]">
            <div className="flex justify-between items-center mb-2">
                <h3 className="text-sm font-semibold text-white flex items-center gap-2"><AlignmentIcon /> Strategic Alignment</h3>
                {alignmentScore !== null && (
                     <span className={`text-lg font-bold ${alignmentScore > 80 ? 'text-green-400' : 'text-yellow-400'}`}>{alignmentScore}%</span>
                )}
            </div>
            {advice ? (
                <p className="text-xs text-gray-400 mb-2">{advice}</p>
            ) : (
                <p className="text-xs text-gray-500 mb-2">Prüfen Sie, ob die operative Arbeit zur Strategie passt.</p>
            )}
            <button onClick={handleCheckAlignment} disabled={isLoading} className="w-full bg-blue-900/30 border border-blue-500/30 text-blue-300 text-xs py-1.5 rounded-full hover:bg-blue-900/50 disabled:opacity-50">
                {isLoading ? 'Prüfe...' : 'Alignment prüfen'}
            </button>
        </div>
    );
};

