export const ObservatoriumTool: React.FC<{ navigateTo: (page: string) => void }> = ({ navigateTo }) => {
    const { tasks, scheduledPosts, campaignBrief, systemLogs } = useTasks();
    const [conductorInput, setConductorInput] = useState('');

