        const completionRate = tasks.length > 0 ? Math.round((doneCount / tasks.length) * 100) : 0;
        const publishedCount = scheduledPosts.length;
        return { inProgressCount, completionRate, publishedCount };
    }, [tasks, scheduledPosts]);

    const topPerforming = useMemo(() => {
        return [...tasks]
            .filter(t => t.performanceData)
            .sort((a, b) => (b.performanceData.engagementRate || 0) - (a.performanceData.engagementRate || 0))
            .slice(0, 3);
