                        <textarea 
                            value={conductorInput}
                            onChange={e => setConductorInput(e.target.value)}
                            placeholder="z.B. 'Entwickle eine Strategie für unsere neue Produkt-Launch'..." 
                            className="w-full h-24 bg-[#1C1C1C] text-white text-sm p-3 rounded-md border border-[#333333] resize-none"
                        />
                        <button type="submit" className="w-full mt-2 bg-purple-600 text-white text-sm py-2 rounded-full hover:bg-purple-500 disabled:opacity-50" disabled={!conductorInput.trim()}>
                            An Conductor delegieren
