                    <h3 className="text-sm font-semibold text-white mb-2">Top-Performer (Engagement)</h3>
                    <div className="space-y-2">
                        {topPerforming.length > 0 ? topPerforming.map(task => (
                            <div key={task.id} className="text-xs flex justify-between items-center">
                                <span className="text-gray-300 truncate pr-4">{task.title}</span>
                                <span className="font-bold text-green-400">{task.performanceData.engagementRate}%</span>
