                     printWindow.document.write(`<html><head><title>${item.title}</title></head><body style="font-family: sans-serif; padding: 20px;"><h1>${item.title}</h1><hr/><p>${item.description || item.content}</p></body></html>`);
                     printWindow.document.close();
                     printWindow.print();
                 }
            } else if (action === 'share') {
                navigator.clipboard.writeText(`${item.title}\n${item.description || item.content}`);
                alert("Inhalt in Zwischenablage kopiert.");
