const HomeNav: React.FC = () => {
    const [activeSection, setActiveSection] = useState('hero');

    useEffect(() => {
        const handleScroll = () => {
            const sections = ['hero', 'manifesto', 'philosophy', 'value-prop', 'showcase', 'features', 'pricing'];
            const scrollPosition = window.scrollY + 120; // Offset for header height + buffer

            for (const section of sections) {
                const element = document.getElementById(section);
                if (element) {
                    const { offsetTop, offsetHeight } = element;
                    if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
                        setActiveSection(section);
                        break;
                    }
                }
            }
        };

        window.addEventListener('scroll', handleScroll);
        // Trigger once on mount to set initial state
        handleScroll();
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const scrollToSection = (id: string) => {
        const element = document.getElementById(id);
        if (element) {
            const headerOffset = 110; 
            const elementPosition = element.getBoundingClientRect().top;
            const offsetPosition = elementPosition + window.pageYOffset - headerOffset;
            window.scrollTo({
                top: offsetPosition,
                behavior: "smooth"
            });
        } else {
             window.scrollTo({ top: 0, behavior: 'smooth' });
        }
    };

    const getLinkClass = (id: string) => `whitespace-nowrap transition-colors duration-300 ${activeSection === id ? 'text-white' : 'text-gray-500 hover:text-white'}`;

    return (
        <div className="flex items-center gap-6 text-[11px] uppercase tracking-[2px] font-medium overflow-x-auto w-full md:w-auto px-4 md:px-0 no-scrollbar">
