export const ObservatoriumTool: React.FC<{ navigateTo: (page: string) => void }> = ({ navigateTo }) => {
    const { tasks, documents, systemLogs, userProfile, updateUserProfile, setToolInput } = useTasks();

    const [windows, setWindows] = useState<WindowState[]>([]);
    const [activeWindowId, setActiveWindowId] = useState<string | null>(null);
    const [startMenuOpen, setStartMenuOpen] = useState(false);
    const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
    const [currentTime, setCurrentTime] = useState(new Date());
    const [highestZ, setHighestZ] = useState(100);

    // Dragging State
    const [isDragging, setIsDragging] = useState<{id: string, startX: number, startY: number, initialX: number, initialY: number} | null>(null);

    useEffect(() => {
        const timer = setInterval(() => setCurrentTime(new Date()), 1000);
        // Init default windows
        openWindow('terminal', 'Mission Core');
        return () => clearInterval(timer);
    }, []);

    // Window Management
    const openWindow = (appId: AppId, title: string, contentProps: any = null) => {
        const existing = windows.find(w => w.appId === appId && appId !== 'viewer'); // Viewer allows multiple
        if (existing) {
            focusWindow(existing.id);
            if (existing.isMinimized) toggleMinimize(existing.id);
            return;
        }

        const id = `${appId}-${Date.now()}`;
        let width = 800, height = 600;
        if (appId === 'mission') { width = 500; height = 450; }
        if (appId === 'terminal') { width = 600; height = 400; }
        if (appId === 'monitor') { width = 700; height = 500; }
        if (appId === 'settings') { width = 400; height = 350; }

        const newWin: WindowState = {
            id, appId, title,
            x: 50 + (windows.length * 20),
            y: 50 + (windows.length * 20),
            width, height, zIndex: highestZ + 1,
            isMinimized: false, isMaximized: false,
            contentProps
        };

        setWindows(prev => [...prev, newWin]);
        setHighestZ(prev => prev + 1);
        setActiveWindowId(id);
        setStartMenuOpen(false);
    };

    const closeWindow = (id: string) => {
        setWindows(prev => prev.filter(w => w.id !== id));
        if (activeWindowId === id) setActiveWindowId(null);
    };

    const focusWindow = (id: string) => {
        setActiveWindowId(id);
        setWindows(prev => prev.map(w => w.id === id ? { ...w, zIndex: highestZ + 1 } : w));
        setHighestZ(prev => prev + 1);
    };

    const toggleMinimize = (id: string) => {
        setWindows(prev => prev.map(w => w.id === id ? { ...w, isMinimized: !w.isMinimized } : w));
        if (activeWindowId === id) setActiveWindowId(null);
    };

    const toggleMaximize = (id: string) => {
        setWindows(prev => prev.map(w => w.id === id ? { ...w, isMaximized: !w.isMaximized } : w));
        focusWindow(id);
    };

    // Interaction Handlers
    const handleMouseDown = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        focusWindow(id);
        const win = windows.find(w => w.id === id);
        if (win && !win.isMaximized) {
            setIsDragging({ id, startX: e.clientX, startY: e.clientY, initialX: win.x, initialY: win.y });
        }
    };

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                const deltaX = e.clientX - isDragging.startX;
                const deltaY = e.clientY - isDragging.startY;
                setWindows(prev => prev.map(w => w.id === isDragging.id ? { ...w, x: isDragging.initialX + deltaX, y: isDragging.initialY + deltaY } : w));
            }
        };
        const handleMouseUp = () => setIsDragging(null);
        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging]);

    const handleContextMenu = (e: React.MouseEvent, type: 'desktop' | 'file', item?: Task | Document) => {
        e.preventDefault();
        e.stopPropagation();
        setContextMenu({ x: e.clientX, y: e.clientY, type, item });
    };

    const handleContextAction = (action: string) => {
        const item = contextMenu?.item as any;
        if (contextMenu?.type === 'file' && item) {
             if (action === 'visionar') {
                setToolInput({ tool: 'visionar', prompt: item.description || item.title, sourceTaskId: item.id || -1 });
                navigateTo('visionar');
            } else if (action === 'publisher') {
                setToolInput({ tool: 'publisher', sourceTaskId: item.id || -1 });
                navigateTo('publisher');
            } else if (action === 'print') {
                 const printWindow = window.open('', '', 'width=600,height=600');
                 if(printWindow) {
                     printWindow.document.write(`<html><head><title>${item.title}</title></head><body style="font-family: sans-serif; padding: 20px;"><h1>${item.title}</h1><hr/><p>${item.description || item.content}</p></body></html>`);
                     printWindow.document.close();
                     printWindow.print();
                 }
            } else if (action === 'share') {
                navigator.clipboard.writeText(`${item.title}\n${item.description || item.content}`);
                alert("Inhalt in Zwischenablage kopiert.");
            }
        }
        setContextMenu(null);
    };

    const handleUpdateMission = (mission: string) => {
        if (userProfile) updateUserProfile({ ...userProfile, mission });
        else updateUserProfile({ name: 'User', role: 'Admin', organization: 'Default', mission });
    };

    const AGENTS = [
        { id: 'conductor', name: 'Conductor', desc: 'Orchestration' },
        { id: 'stratege', name: 'Stratege', desc: 'Strategy' },
        { id: 'visionar', name: 'Visionär', desc: 'Visuals' },
        { id: 'resonator', name: 'Resonator', desc: 'Social' },
        { id: 'analytiker', name: 'Analytiker', desc: 'Data' },
    ];

    return (
        <div className="fixed inset-0 bg-[#050505] text-white overflow-hidden select-none pt-[80px]" onClick={() => { setStartMenuOpen(false); setContextMenu(null); }}>
            <style>{`
                .bg-grid-pattern { background-image: radial-gradient(circle, rgba(255,255,255,0.03) 1px, transparent 1px); background-size: 40px 40px; }
                .crt::before { content: " "; display: block; position: absolute; top: 0; left: 0; bottom: 0; right: 0; background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06)); z-index: 2; background-size: 100% 2px, 3px 100%; pointer-events: none; }
            `}</style>

            {/* DESKTOP */}
            <div className="absolute inset-0 z-0 bg-grid-pattern crt" onContextMenu={(e) => handleContextMenu(e, 'desktop')}>
                 <div className="absolute top-8 left-6 flex flex-col gap-8">
                     <div className="flex flex-col items-center gap-2 cursor-pointer group w-20" onDoubleClick={() => openWindow('mission', 'Prime Directive')}>
                        <div className="w-14 h-14 bg-white/5 rounded-xl group-hover:bg-white/10 border border-transparent group-hover:border-red-500/50 transition-all text-red-500 flex items-center justify-center shadow-lg">
                            <TargetIcon />
                        </div>
                        <span className="text-[10px] font-medium text-gray-400 text-center bg-black/60 rounded px-2 py-0.5 group-hover:text-white shadow-md backdrop-blur-sm">Mission</span>
                    </div>
                    <div className="flex flex-col items-center gap-2 cursor-pointer group w-20" onDoubleClick={() => openWindow('explorer', 'Asset Explorer')}>
                        <div className="w-14 h-14 bg-white/5 rounded-xl group-hover:bg-white/10 border border-transparent group-hover:border-yellow-500/50 transition-all text-yellow-500 flex items-center justify-center shadow-lg">
                            <FolderIcon />
                        </div>
                        <span className="text-[10px] font-medium text-gray-400 text-center bg-black/60 rounded px-2 py-0.5 group-hover:text-white shadow-md backdrop-blur-sm">Explorer</span>
                    </div>
                    <div className="flex flex-col items-center gap-2 cursor-pointer group w-20" onDoubleClick={() => openWindow('terminal', 'Mission Core')}>
                        <div className="w-14 h-14 bg-white/5 rounded-xl group-hover:bg-white/10 border border-transparent group-hover:border-green-500/50 transition-all text-green-500 flex items-center justify-center shadow-lg">
                            <TerminalWindowIcon />
                        </div>
                        <span className="text-[10px] font-medium text-gray-400 text-center bg-black/60 rounded px-2 py-0.5 group-hover:text-white shadow-md backdrop-blur-sm">Terminal</span>
                    </div>
                    <div className="flex flex-col items-center gap-2 cursor-pointer group w-20" onDoubleClick={() => openWindow('monitor', 'Neural Monitor')}>
                        <div className="w-14 h-14 bg-white/5 rounded-xl group-hover:bg-white/10 border border-transparent group-hover:border-blue-400/50 transition-all text-blue-400 flex items-center justify-center shadow-lg">
                            <MonitorIcon />
                        </div>
