const HomeNav: React.FC = () => {
    const [activeSection, setActiveSection] = useState('hero');

    useEffect(() => {
        const handleScroll = () => {
            const sections = ['hero', 'manifesto', 'philosophy', 'value-prop', 'showcase', 'features', 'pricing'];
            const scrollPosition = window.scrollY + 120; // Offset for header height + buffer

            for (const section of sections) {
                const element = document.getElementById(section);
                if (element) {
                    const { offsetTop, offsetHeight } = element;
                    if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
                        setActiveSection(section);
                        break;
                    }
                }
            }
        };

        window.addEventListener('scroll', handleScroll);
        // Trigger once on mount to set initial state
        handleScroll();
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const scrollToSection = (id: string) => {
        const element = document.getElementById(id);
        if (element) {
            const headerOffset = 110; 
            const elementPosition = element.getBoundingClientRect().top;
            const offsetPosition = elementPosition + window.pageYOffset - headerOffset;
            window.scrollTo({
                top: offsetPosition,
                behavior: "smooth"
            });
        } else {
             window.scrollTo({ top: 0, behavior: 'smooth' });
        }
    };

    const getLinkClass = (id: string) => `whitespace-nowrap transition-colors duration-300 ${activeSection === id ? 'text-white' : 'text-gray-500 hover:text-white'}`;

    return (
        <div className="flex items-center gap-6 text-[11px] uppercase tracking-[2px] font-medium overflow-x-auto w-full md:w-auto px-4 md:px-0 no-scrollbar">
            <style>{`.no-scrollbar::-webkit-scrollbar { display: none; } .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }`}</style>
            <button onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} className={getLinkClass('hero')}>Start</button>
            <button onClick={() => scrollToSection('manifesto')} className={getLinkClass('manifesto')}>Vision</button>
            <button onClick={() => scrollToSection('philosophy')} className={getLinkClass('philosophy')}>Philosophie</button>
            <button onClick={() => scrollToSection('value-prop')} className={getLinkClass('value-prop')}>Problem</button>
            <button onClick={() => scrollToSection('showcase')} className={getLinkClass('showcase')}>Showcase</button>
            <button onClick={() => scrollToSection('features')} className={getLinkClass('features')}>Suite</button>
            <button onClick={() => scrollToSection('pricing')} className={getLinkClass('pricing')}>Preise</button>
        </div>
    );
};

const ToolBreadcrumbs: React.FC<{ currentPage: string; navigateTo: (page: string) => void }> = ({ currentPage, navigateTo }) => {
    // Mapping categories based on the navigation structure
    let category = "App";

    const strategyPages = ['dirigent', 'stratege', 'analytiker', 'orakel', 'ensemble', 'spaeher', 'experimentator', 'berichterstatter', 'kalkulator', 'statusbericht', 'interimmanager'];
    const creationPages = ['visionar', 'animator', 'kolorit', 'baumeister', 'personalisator', 'resonator', 'emailmarketing', 'meisterwerk'];
    const automationPages = ['conductor', 'sequenzer', 'taktgeber', 'publisher'];
    const systemPages = ['nexus', 'prometheus', 'systemaudit', 'akademie', 'markenwaechter', 'masterplan'];
    const commsPages = ['diplomat', 'chronist', 'gespraechsleiter', 'auditorium', 'konversator'];

    if (strategyPages.includes(currentPage)) category = "Strategie & Analyse";
    else if (creationPages.includes(currentPage)) category = "Kreation & Produktion";
    else if (automationPages.includes(currentPage)) category = "Automation";
    else if (systemPages.includes(currentPage)) category = "System Core";
    else if (commsPages.includes(currentPage)) category = "Kommunikation";

    return (
        <div className="flex items-center gap-2 text-xs animate-[fadeIn_0.3s_ease-out] whitespace-nowrap overflow-hidden">
            <button onClick={() => navigateTo('home')} className="text-gray-500 hover:text-white transition-colors flex-shrink-0">Home</button>
            <ChevronRight />
            <span className="text-gray-500 flex-shrink-0 hidden sm:inline">{category}</span>
            <span className="text-gray-500 flex-shrink-0 sm:hidden">...</span>
            <ChevronRight />
            <span className="text-purple-400 font-medium capitalize tracking-wide truncate">{currentPage}</span>
        </div>
    );
};

